{"refs":["alphabet","length","modulus","residue","sum_min","sum_max","target_digit","target_count"],"code":"def solve(facts):
    alphabet=facts['alphabet']; n=facts['length']; mod=facts['modulus']; residue=facts['residue']; lo=facts['sum_min']; hi=facts['sum_max']; target=facts['target_digit']; need=facts['target_count']
    dp={(0,0,0,None):(1,0)}
    for _ in range(n):
        nd={}
        for (r,s,c,last),(ways,total) in dp.items():
            for d in alphabet:
                if last is not None and d==last: continue
                nc=c+(d==target); ns=s+d
                if nc>need or ns>hi: continue
                key=((r*10+d)%mod,ns,nc,d)
                w,t=nd.get(key,(0,0)); nd[key]=(w+ways,t+total+ways*d)
        dp=nd
    count=total=0
    for (r,s,c,last),(w,t) in dp.items():
        if r==residue and lo<=s<=hi and c==need: count+=w; total+=t
    return {'count':count,'digit_sum_total':total}
def check(answer,facts):
    alphabet=facts['alphabet']; n=facts['length']; mod=facts['modulus']; residue=facts['residue']; lo=facts['sum_min']; hi=facts['sum_max']; target=facts['target_digit']; need=facts['target_count']
    states={(0,0,0,None)}
    for _ in range(n):
        nxt=set()
        for r,s,c,last in states:
            for d in alphabet:
                if last is not None and d==last: continue
                ns=s+d; nc=c+(d==target)
                if ns<=hi and nc<=need: nxt.add(((r*10+d)%mod,ns,nc,d))
        states=nxt
    count=total=0
    for r,s,c,last in states:
        if r==residue and lo<=s<=hi and c==need: count+=1; total+=s
    return isinstance(answer,dict) and answer.get('count')==count and answer.get('digit_sum_total')==total"}

